INSERT INTO "portal_announcement" VALUES(1,'Welcome to Academic Year 2026-2027!','CSBO welcomes all freshmen and returning DMMMSU-NLUC students. Check your digital ID and calendar.','general','2026-10-05 16:42:58.990330',1,2);
INSERT INTO "portal_announcement" VALUES(2,'Mandatory Attendance: CSBO General Assembly','All students are required to attend the semestral assembly at the Audio Visual Hall. QR scanning is active.','event','2026-10-05 16:42:59.023366',1,2);
INSERT INTO "portal_announcement" VALUES(3,'Midterm Clearance Process is Now Open','Clearance checklists have been generated for all enrolled students. Please review pending items in your clearance tab.','clearance','2026-10-05 16:42:59.048961',1,2);
INSERT INTO "portal_announcement" VALUES(4,'Intramural Sports Fest Registration Guidelines','Colleges may now register teams for basketball, volleyball, athletics, and chess at the Sports Center.','event','2026-10-05 16:42:59.074681',1,2);
INSERT INTO "portal_announcement" VALUES(5,'Main Library Book Amnesty & Return Notice','Return all overdue books this week with waived late fees. Visit the circulation desk for clearance signing.','clearance','2026-10-05 16:42:59.102130',1,2);
INSERT INTO "portal_announcement" VALUES(6,'Tech & Innovation Summit Call for Project Entries','Submissions for software, hardware, and sustainable tech prototypes are open until Friday.','event','2026-10-05 16:42:59.127123',1,2);
INSERT INTO "portal_announcement" VALUES(7,'Digital Student ID & QR Attendance Policy','Present your ISAC Portal Digital ID on your phone at every campus activity entrance for instantaneous scanning.','general','2026-10-05 16:42:59.152983',1,2);
INSERT INTO "portal_announcement" VALUES(8,'Campus Mental Health & Wellness Week','Free counseling, yoga workshops, and stress relief booths will be available at the Gymnasium Annex.','general','2026-10-05 16:42:59.178535',1,2);
INSERT INTO "portal_announcement" VALUES(9,'Urgent: Validate Your University ID RFID Stickers','Students without validated 1st Semester stickers will be flagged at campus security gates.','urgent','2026-10-05 16:42:59.203475',1,2);
INSERT INTO "portal_announcement" VALUES(10,'Inter-College Hackathon 2026 Cash Prizes Announced','Over PHP 50,000 in prizes await the top winning software development teams.','event','2026-10-05 16:42:59.227929',1,2);
INSERT INTO "portal_announcement" VALUES(11,'Community Extension Tree Planting Volunteers Needed','Earn 2 participation points and clear your environmental requirement by joining the eco-park drive.','event','2026-10-05 16:42:59.253437',1,2);
INSERT INTO "portal_announcement" VALUES(12,'Notice on Pending Clearance Fines and Dues','Students with unpaid fines must settle with the CSBO Treasurer before final exam permits are released.','clearance','2026-10-05 16:42:59.277764',1,2);
INSERT INTO "portal_announcement" VALUES(13,'Annual Career Fair: 40+ Industry Employers Confirmed','Bring your printed resumes and wear business casual attire to the Student Activity Center.','event','2026-10-05 16:42:59.301569',1,2);
INSERT INTO "portal_announcement" VALUES(14,'CSBO Acquaintance Night Ticket Distribution','Claim your official event wristbands from your respective college representatives.','event','2026-10-05 16:42:59.326329',1,2);
INSERT INTO "portal_announcement" VALUES(15,'Cultural Arts Festival Auditions Ongoing','Singers, dancers, and theater performers are encouraged to audition at the Main Auditorium.','event','2026-10-05 16:42:59.352051',1,2);
INSERT INTO "portal_announcement" VALUES(16,'Student Leadership Seminar Participant Slots','Class presidents and organization officers are requested to confirm attendance by Wednesday.','event','2026-10-05 16:42:59.376114',1,2);
INSERT INTO "portal_announcement" VALUES(17,'Red Cross Blood Donation Drive Registration','Be a hero and save lives. Blood donors will receive 2 participation points and certificate of appreciation.','general','2026-10-05 16:42:59.402472',1,2);
INSERT INTO "portal_announcement" VALUES(18,'Cybersecurity & Data Privacy Advisory','Never share your ISAC portal passwords or scan tokens with anyone. Report phishing attempts to MIS.','urgent','2026-10-05 16:42:59.427504',1,2);
INSERT INTO "portal_announcement" VALUES(19,'Disaster Preparedness Simulation Drill','A campus-wide earthquake and fire evacuation drill will be held at 9:00 AM next Tuesday.','general','2026-10-05 16:42:59.452996',1,2);
