BEGIN TRANSACTION;
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "first_name" varchar(150) NOT NULL);
CREATE TABLE "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE "portal_announcement" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(180) NOT NULL, "body" text NOT NULL, "category" varchar(20) NOT NULL, "published_at" datetime NOT NULL, "status" bool NOT NULL, "published_by_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "portal_attendancerecord" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "scanned_at" datetime NOT NULL, "status" varchar(20) NOT NULL, "scanned_by_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "event_id" bigint NOT NULL REFERENCES "portal_event" ("id") DEFERRABLE INITIALLY DEFERRED, "student_id" bigint NOT NULL REFERENCES "portal_profile" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "unique_event_student" UNIQUE ("event_id", "student_id"));
CREATE TABLE "portal_auditlog" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "action" varchar(120) NOT NULL, "details" text NOT NULL, "created_at" datetime NOT NULL, "user_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "portal_clearancerecord" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "status" varchar(20) NOT NULL, "updated_at" datetime NOT NULL, "updated_by_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "requirement_id" bigint NOT NULL REFERENCES "portal_clearancerequirement" ("id") DEFERRABLE INITIALLY DEFERRED, "student_id" bigint NOT NULL REFERENCES "portal_profile" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "unique_clearance" UNIQUE ("student_id", "requirement_id"));
CREATE TABLE "portal_clearancerequirement" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL, "description" text NOT NULL, "required_points" integer unsigned NOT NULL CHECK ("required_points" >= 0), "required_events" integer unsigned NOT NULL CHECK ("required_events" >= 0));
CREATE TABLE "portal_college" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code" varchar(20) NOT NULL UNIQUE, "name" varchar(150) NOT NULL);
CREATE TABLE "portal_event" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(180) NOT NULL, "description" text NOT NULL, "venue" varchar(180) NOT NULL, "event_date" date NOT NULL, "start_time" time NOT NULL, "end_time" time NOT NULL, "points" integer unsigned NOT NULL CHECK ("points" >= 0), "status" varchar(20) NOT NULL, "created_at" datetime NOT NULL, "created_by_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "portal_fine" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "reason" varchar(220) NOT NULL, "amount" decimal NOT NULL, "status" varchar(20) NOT NULL, "verified_at" datetime NULL, "created_at" datetime NOT NULL, "event_id" bigint NULL REFERENCES "portal_event" ("id") DEFERRABLE INITIALLY DEFERRED, "recorded_by_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "student_id" bigint NOT NULL REFERENCES "portal_profile" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "portal_participationpoint" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "points" integer unsigned NOT NULL CHECK ("points" >= 0), "awarded_at" datetime NOT NULL, "event_id" bigint NOT NULL REFERENCES "portal_event" ("id") DEFERRABLE INITIALLY DEFERRED, "student_id" bigint NOT NULL REFERENCES "portal_profile" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "unique_student_event_points" UNIQUE ("student_id", "event_id"));
CREATE TABLE "portal_profile" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "role" varchar(20) NOT NULL, "student_no" varchar(30) NULL UNIQUE, "first_name" varchar(80) NOT NULL, "middle_name" varchar(80) NOT NULL, "last_name" varchar(80) NOT NULL, "year_level" smallint unsigned NOT NULL CHECK ("year_level" >= 0), "photo" varchar(100) NULL, "qr_token" char(32) NOT NULL UNIQUE, "position" varchar(100) NOT NULL, "college_id" bigint NULL REFERENCES "portal_college" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL UNIQUE REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "program_id" bigint NULL REFERENCES "portal_program" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "portal_program" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL, "college_id" bigint NOT NULL REFERENCES "portal_college" ("id") DEFERRABLE INITIALLY DEFERRED);
